using System.Text.Json;using JobOrbit.Application.DTOs.HiringDecisions;using JobOrbit.Application.DTOs.Jobs;using JobOrbit.Application.DTOs.Notifications;using JobOrbit.Application.Interfaces;using JobOrbit.Domain;using JobOrbit.Domain.Entities;using JobOrbit.Domain.Enums;using Microsoft.EntityFrameworkCore;
namespace JobOrbit.Infrastructure.Persistence.Repositories;
public sealed class HiringDecisionRepository(JobOrbitDbContext db,ISystemSettingsProvider systemSettings,INotificationService notifications):IHiringDecisionRepository
{
 async Task<(int Org,int? Dept)?>Scope(int id,CancellationToken t){var x=await db.HiringManagerProfiles.AsNoTracking().Where(x=>x.UserId==id&&x.User.IsActive).Select(x=>new{x.OrganizationId,x.DepartmentId}).SingleOrDefaultAsync(t);return x is null?null:(x.OrganizationId,x.DepartmentId);}IQueryable<JobApplication>Apps((int Org,int? Dept)s)=>db.JobApplications.Where(x=>x.JobPosting.OrganizationId==s.Org&&(!s.Dept.HasValue||x.JobPosting.DepartmentId==s.Dept));
 public async Task<PagedResultDto<HiringDecisionListItemDto>>ListAsync(int id,HiringDecisionQuery q,CancellationToken t=default){var s=await Scope(id,t);if(s is null)return new(){Page=q.Page,PageSize=q.PageSize};var a=Apps(s.Value).AsNoTracking().Where(x=>x.CandidateEvaluations.Any(e=>e.EvaluatorUserId!=null));if(q.JobId.HasValue)a=a.Where(x=>x.JobPostingId==q.JobId);if(!string.IsNullOrWhiteSpace(q.Decision)){if(q.Decision.Equals("Pending",StringComparison.OrdinalIgnoreCase))a=a.Where(x=>x.HiringDecision==null);else if(Enum.TryParse<ManagerHiringDecision>(q.Decision,true,out var d))a=a.Where(x=>x.HiringDecision!=null&&x.HiringDecision.Decision==d);}if(!string.IsNullOrWhiteSpace(q.Search)){var term=q.Search.Trim();a=a.Where(x=>(x.CandidateProfile.User.FirstName+" "+x.CandidateProfile.User.LastName).Contains(term)||x.JobPosting.Title.Contains(term));}a=q.Sort.ToLowerInvariant() switch{"oldest"=>a.OrderBy(x=>x.AppliedAt),"name"=>a.OrderBy(x=>x.CandidateProfile.User.FirstName),_=>a.OrderByDescending(x=>x.HiringDecision!=null?x.HiringDecision.DecidedAt:x.AppliedAt)};var total=await a.CountAsync(t);var items=await a.Skip((q.Page-1)*q.PageSize).Take(q.PageSize).Select(x=>new HiringDecisionListItemDto{ApplicationId=x.Id,CandidateName=x.CandidateProfile.User.FirstName+" "+x.CandidateProfile.User.LastName,JobId=x.JobPostingId,JobTitle=x.JobPosting.Title,OverallScore=x.CandidateEvaluations.Where(e=>e.EvaluatorUserId!=null).Average(e=>e.OverallScore),Recommendation=x.CandidateEvaluations.Where(e=>e.EvaluatorUserId!=null).OrderByDescending(e=>e.CreatedAt).Select(e=>e.Recommendation!.Value.ToString()).FirstOrDefault()??"Hold",Decision=x.HiringDecision==null?"Pending":x.HiringDecision.Decision.ToString(),DecidedOn=x.HiringDecision==null?null:x.HiringDecision.DecidedAt}).ToListAsync(t);return new(){Items=items,Page=q.Page,PageSize=q.PageSize,TotalItems=total,TotalPages=(int)Math.Ceiling(total/(double)q.PageSize)};}
 public async Task<HiringDecisionDetailsDto?>DetailsAsync(int id,int appId,CancellationToken t=default){var s=await Scope(id,t);if(s is null)return null;var x=await Apps(s.Value).AsNoTracking().Where(x=>x.Id==appId&&x.CandidateEvaluations.Any(e=>e.EvaluatorUserId!=null)).Select(x=>new HiringDecisionDetailsDto{ApplicationId=x.Id,CandidateName=x.CandidateProfile.User.FirstName+" "+x.CandidateProfile.User.LastName,ProfessionalTitle=x.CandidateProfile.Headline,JobId=x.JobPostingId,JobTitle=x.JobPosting.Title,ApplicationStatus=x.Status.ToString(),InterviewStatus=x.Interviews.OrderByDescending(i=>i.ScheduledAt).Select(i=>i.Status.ToString()).FirstOrDefault(),InterviewDate=x.Interviews.OrderByDescending(i=>i.ScheduledAt).Select(i=>(DateTime?)i.ScheduledAt).FirstOrDefault(),Evaluations=x.CandidateEvaluations.Where(e=>e.EvaluatorUserId!=null).OrderByDescending(e=>e.CreatedAt).Select(e=>new HiringDecisionEvaluationDto{EvaluationId=e.Id,OverallScore=e.OverallScore,Recommendation=e.Recommendation!.Value.ToString(),EvaluatorName=e.EvaluatorUser!.FirstName+" "+e.EvaluatorUser.LastName,Comments=e.Comments,EvaluatedAt=e.CreatedAt}).ToList(),OverallScore=x.CandidateEvaluations.Where(e=>e.EvaluatorUserId!=null).Average(e=>e.OverallScore),Recommendation=x.CandidateEvaluations.Where(e=>e.EvaluatorUserId!=null).OrderByDescending(e=>e.CreatedAt).Select(e=>e.Recommendation!.Value.ToString()).First(),Decision=x.HiringDecision==null?"Pending":x.HiringDecision.Decision.ToString(),DecisionNotes=x.HiringDecision==null?null:x.HiringDecision.Notes,DecidedBy=x.HiringDecision==null?null:x.HiringDecision.DecidedByUser.FirstName+" "+x.HiringDecision.DecidedByUser.LastName,DecidedAt=x.HiringDecision==null?null:x.HiringDecision.DecidedAt,IsFinal=x.HiringDecision!=null&&(x.HiringDecision.Decision==ManagerHiringDecision.Hire||x.HiringDecision.Decision==ManagerHiringDecision.Reject)}).SingleOrDefaultAsync(t);return x;}
 public async Task<HiringDecisionMutationResult>CreateAsync(int id,int appId,ManagerHiringDecision d,string? notes,CancellationToken t=default){var s=await Scope(id,t);if(s is null)return new(HiringDecisionMutationOutcome.NotFound);var a=await Apps(s.Value).Include(x=>x.HiringDecision).Include(x=>x.CandidateProfile).Include(x=>x.JobPosting).ThenInclude(x=>x.RecruiterProfile).SingleOrDefaultAsync(x=>x.Id==appId,t);if(a is null)return new(HiringDecisionMutationOutcome.NotFound);var rules=(await systemSettings.GetAsync(t)).Recruitment;if(rules.RequireEvaluationBeforeHiringDecision&&!await db.CandidateEvaluations.AnyAsync(x=>x.JobApplicationId==appId&&x.EvaluatorUserId!=null,t))return new(HiringDecisionMutationOutcome.NoEvaluation);if(rules.RequireInterviewBeforeHiringDecision&&!await db.Interviews.AnyAsync(x=>x.JobApplicationId==appId&&x.Status==InterviewStatus.Completed,t))return new(HiringDecisionMutationOutcome.NoInterview);if(a.HiringDecision!=null)return new(a.HiringDecision.Decision is ManagerHiringDecision.Hire or ManagerHiringDecision.Reject?HiringDecisionMutationOutcome.DuplicateFinal:HiringDecisionMutationOutcome.InvalidTransition);var now=DateTime.UtcNow;a.HiringDecision=new(){DecidedByUserId=id,Decision=d,Notes=notes,DecidedAt=now};if(d==ManagerHiringDecision.Hire)a.Status=ApplicationStatus.Hired;else if(d==ManagerHiringDecision.Reject)a.Status=ApplicationStatus.Rejected;db.AuditLogs.Add(new AuditLog{UserId=id,EntityName=nameof(ApplicationHiringDecision),EntityId=appId,Action="CreateHiringDecision",NewValues=JsonSerializer.Serialize(new{Decision=d.ToString(),Notes=notes})});await db.SaveChangesAsync(t);await DecisionNotifications(a,d,t);return new(HiringDecisionMutationOutcome.Success,await DetailsAsync(id,appId,t));}
 public async Task<HiringDecisionMutationResult>UpdateAsync(int id,int appId,ManagerHiringDecision d,string? notes,CancellationToken t=default){var s=await Scope(id,t);if(s is null)return new(HiringDecisionMutationOutcome.NotFound);var a=await Apps(s.Value).Include(x=>x.HiringDecision).Include(x=>x.CandidateProfile).Include(x=>x.JobPosting).ThenInclude(x=>x.RecruiterProfile).SingleOrDefaultAsync(x=>x.Id==appId,t);if(a?.HiringDecision is null||a.HiringDecision.DecidedByUserId!=id)return new(HiringDecisionMutationOutcome.NotFound);if(a.HiringDecision.Decision is ManagerHiringDecision.Hire or ManagerHiringDecision.Reject)return new(HiringDecisionMutationOutcome.InvalidTransition);a.HiringDecision.Decision=d;a.HiringDecision.Notes=notes;a.HiringDecision.DecidedAt=DateTime.UtcNow;if(d==ManagerHiringDecision.Hire)a.Status=ApplicationStatus.Hired;else if(d==ManagerHiringDecision.Reject)a.Status=ApplicationStatus.Rejected;db.AuditLogs.Add(new AuditLog{UserId=id,EntityName=nameof(ApplicationHiringDecision),EntityId=a.HiringDecision.Id,Action="UpdateHiringDecision",NewValues=JsonSerializer.Serialize(new{Decision=d.ToString(),Notes=notes})});await db.SaveChangesAsync(t);await DecisionNotifications(a,d,t);return new(HiringDecisionMutationOutcome.Success,await DetailsAsync(id,appId,t));}
 public async Task<HiringFunnelDto>FunnelAsync(int id,CancellationToken t=default){var s=await Scope(id,t);if(s is null)return new();var a=Apps(s.Value).AsNoTracking();return new(){Shortlisted=await a.CountAsync(x=>x.Status==ApplicationStatus.Shortlisted,t),Interviewed=await a.CountAsync(x=>x.Interviews.Any(i=>i.Status==InterviewStatus.Completed),t),Evaluated=await a.CountAsync(x=>x.CandidateEvaluations.Any(e=>e.EvaluatorUserId!=null),t),Held=await a.CountAsync(x=>x.HiringDecision!=null&&x.HiringDecision.Decision==ManagerHiringDecision.Hold,t),Hired=await a.CountAsync(x=>x.Status==ApplicationStatus.Hired,t),Rejected=await a.CountAsync(x=>x.Status==ApplicationStatus.Rejected,t)};}
 private Task<int>DecisionNotifications(JobApplication a,ManagerHiringDecision d,CancellationToken t)=>notifications.CreateManyAsync([new(a.CandidateProfile.UserId,NotificationTypes.HiringDecisionUpdated,"Hiring decision updated",$"A hiring decision for {a.JobPosting.Title} is available.",nameof(ApplicationHiringDecision),a.HiringDecision!.Id,$"/candidate/applications/{a.Id}",EventKey:$"decision:{a.HiringDecision.Id}:{d}:candidate"),new(a.JobPosting.RecruiterProfile.UserId,NotificationTypes.InterviewStatusChanged,"Hiring decision updated",$"A hiring decision for {a.JobPosting.Title} was recorded.",nameof(ApplicationHiringDecision),a.HiringDecision.Id,$"/recruiter/applicants/{a.Id}",EventKey:$"decision:{a.HiringDecision.Id}:{d}:recruiter")],t);
}
